import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    prices = [int(x) for x in input_data[1:n+1]]

    prices.sort(reverse=True)

    total = 0
    for i in range(n):
        if (i + 1) % 3 != 0:
            total += prices[i]

    print(total)

if __name__ == '__main__':
    main()
